export function minCoinsForAmount(coins, amount) {
    const dp = Array(amount + 1).fill(Infinity);
    dp[0] = 0;
    for (let a = 1; a <= amount; a++)
        for (const c of coins)
            if (c > 0 && c <= a)
                dp[a] = Math.min(dp[a], dp[a - c] + 1);
    return Number.isFinite(dp[amount]) ? dp[amount] : -1;
}
